import net.runelite.client.util.ImageUtil;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;

import static com.PetTraining.PetSkill.*;

public class PetTrainingPanel extends PluginPanel {
        @Inject
        private Client client;

        @Inject
        private EventBus eventBus;

        private final SpriteManager spriteManager;
        private final PetTrainingPlugin plugin;

        private final PetSkill[] SKILLS = {
                ATTACK, HITPOINTS, MINING,
                STRENGTH, AGILITY, SMITHING,
                DEFENCE, HERBLORE, FISHING,
                RANGED, THIEVING, COOKING,
                PRAYER, CRAFTING, FIREMAKING,
                MAGIC, FLETCHING, WOODCUTTING,
                RUNECRAFT, SLAYER, FARMING,
                CONSTRUCTION, HUNTER, SAILING
        };

        private final Map<PetSkill, JLabel> skillLabels = new HashMap<>();
        private final JLabel nameLabel;
        private final JPanel dropdownPanel;
        public GridBagConstraints constraints;

        private Boolean displayedIsFollower = false;
        private String displayName;
        private PetLevels displayedPetLevels;

        void init()
        {
            //
        }

    @Inject
    public PetTrainingPanel(SpriteManager spriteManager, PetTrainingPlugin plugin) {
        this.spriteManager = spriteManager;
        this.plugin = plugin;

        // Expand sub items to fit width of panel, align to top of panel
        GridBagConstraints c = new GridBagConstraints();
        c.fill = GridBagConstraints.HORIZONTAL;
        c.gridx = 0;
        c.gridy = 0;
        c.weightx = 1;
        c.weighty = 0;
        c.insets = new Insets(0, 0, 10, 0);

        this.constraints = c;

        // Panel with currently displayed pet's name
        JPanel namePanel = new JPanel();
        JLabel nameLabel = new JLabel();
        nameLabel.setText("No pet selected");

        namePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        namePanel.setBorder(new EmptyBorder(2, 0, 2, 0));
        namePanel.add(nameLabel);
        this.nameLabel = nameLabel;
        add(namePanel, c);
        c.gridy++;

        // Panel that holds skill icons
        JPanel statsPanel = new JPanel();
        statsPanel.setLayout(new GridLayout(8, 3));
        statsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        statsPanel.setBorder(new EmptyBorder(5, 0, 5, 0));

        // For each skill on the in-game skill panel, create a Label and add it to the UI
        //for (String skill : skills)
        for (PetSkill skill: SKILLS)
        {
            JPanel panel = makeSkillPanel(skill);
            statsPanel.add(panel);
        }

        add(statsPanel, c);
        c.gridy++;

        // Panel that holds the dropdown menu
        JPanel dropdownPanel = new JPanel();
        dropdownPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        dropdownPanel.setBorder(new EmptyBorder(0, 0, 0, 0));
        this.dropdownPanel = dropdownPanel;
        add(dropdownPanel, c);
    }

    private Integer getSkillLevel(PetSkill skill){
        Integer level = 0;

        if (displayedIsFollower) {
            level = plugin.getCurrentPetLevels().getLevel(skill.getSkill());
        }
        else if (displayedPetLevels != null) {
            level = displayedPetLevels.getLevel(skill.getSkill());
        }

        return level;
    }

    private JPanel makeSkillPanel(PetSkill skill) {
        JLabel label = new JLabel();
        label.setToolTipText(skill == null ? "Combat" : skill.getName());
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setText("1");

        spriteManager.getSpriteAsync(skill == null ? SpriteID.SideIcons.COMBAT : skill.getSpriteId(), 0, (sprite) ->
                SwingUtilities.invokeLater(() ->
                {
                    // Icons are all 25x25 or smaller, so they're fit into a 25x25 canvas to give them a consistent size for
                    // better alignment. Further, they are then scaled down to 20x20 to not be overly large in the panel.
                    final BufferedImage scaledSprite = ImageUtil.resizeImage(ImageUtil.resizeCanvas(sprite, 25, 25), 20, 20);
                    label.setIcon(new ImageIcon(scaledSprite));
                }));

        label.setIconTextGap(4);

        JPanel skillPanel = new JPanel();
        skillPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        skillPanel.setBorder(new EmptyBorder(2, 0, 2, 0));
        skillLabels.put(skill, label);
        skillPanel.add(label);

        return skillPanel;
    }

    public void setDropdown() {
        dropdownPanel.removeAll(); // get rid of any existing if present

        // Drop down selection box to change the pet
        List<String> dropdownOptions = getDropdownOptions();

        if (dropdownOptions == null) {
            dropdownOptions = new ArrayList<>();
            dropdownOptions.add("No pets to select");
        }
        String[] dropdownArray = dropdownOptions.toArray(new String[0]);

        JComboBox<String> dropdown = new JComboBox<>(dropdownArray);

        if (plugin.getCurrentPetName() != null && dropdownOptions.contains(plugin.getCurrentPetName())) {
            dropdown.setSelectedItem(displayName);
        }

        this.dropdownPanel.add(dropdown);

        dropdown.addActionListener(new ActionListener() {

            public void actionPerformed(ActionEvent e)
            {
                String selectedName = dropdown.getSelectedItem().toString();
                if (selectedName != null) {
                    changeDisplayedPet(selectedName, false);
                }
            }
        });

        add(dropdownPanel, this.constraints);

        dropdownPanel.repaint();
        dropdownPanel.revalidate();
    }


    public void refreshStatPanel(Boolean forceUpdate) {
        repaint();

        if (!forceUpdate) {
            if (displayName != null && !Objects.equals(plugin.getCurrentPetName(), displayName)) {
                return;
            }
        }

        if (displayName == null) {
            this.nameLabel.setText("No current follower");
        }
        else {
            this.nameLabel.setText(displayName);
        }

        // now set the skill values
        for (Map.Entry<PetSkill, JLabel> entry : skillLabels.entrySet()) {
            PetSkill skill = entry.getKey();
            JLabel label = entry.getValue();

            Integer actualLevel = getSkillLevel(skill);
            label.setText(actualLevel == null ? "--" : String.valueOf(actualLevel));

            if (displayedIsFollower) {
                label.setToolTipText(skillToolTip(skill, plugin.getCurrentPetLevels()));
            }
            else if (displayedPetLevels != null) {
                label.setToolTipText(skillToolTip(skill, displayedPetLevels));
            }
            else {
                label.setToolTipText("");
            }
        }

    }

    private String skillToolTip(PetSkill petSkill, PetLevels levels){
        String openingTags = "<html><body style = 'padding: 5px;color:#989898'>";
        String closingTags = "</html><body>";

        String content = "";

        Skill skill = petSkill.getSkill();
        Integer currXp = levels.getXp(skill);
        Integer nextLevel = levels.getExpNextLevel(skill);
        Integer remaining = levels.getRemainingExpToNextLevel(skill);

        content += "<p><span style = 'color:white'>" + skill.getName() + " XP:</span> " + currXp + "</p>";
        content += "<p><span style = 'color:white'>Next level at:</span> " + nextLevel + "</p>";
        content += "<p><span style = 'color:white'>Remaining XP:</span> " + remaining + "</p>";

        return openingTags + content + closingTags;
    }

    private List<String> getDropdownOptions(){
        List<String> availablePets = plugin.getAllSavedPets();

        if (availablePets == null) {
            return null;
        }
        Collections.sort(availablePets);

        return availablePets;
    }

    public void resetDisplayedPet(String name, PetLevels currentPetLevels) {
        displayedIsFollower = false;
        displayName = name;
        displayedPetLevels = currentPetLevels;
    }

    public void changeDisplayedPet(String selectedName, boolean updateDropdown){
        // conditions where nothing changes
        if (Objects.equals(selectedName, "No pets to select")) {
            return;
        }

        displayName = selectedName;

        if (Objects.equals(plugin.getCurrentPetName(), displayName)) {
            displayedIsFollower = true;
            displayedPetLevels = null;
        }
        else {
            displayedIsFollower = false;
            displayedPetLevels = plugin.loadPetStats(selectedName);
        }

        refreshStatPanel(true);
        if (updateDropdown) {
            setDropdown();
        }

    }

}

package com.PetTraining;

import com.google.inject.Provides;
import com.google.gson.Gson;
import com.google.common.base.Strings;
import javax.inject.Inject;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.EnumMap;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigSync;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Pet Training",
	description = "Let your pets gain levels by watching you train."
)
public class PetTrainingPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private PetTrainingConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	private PetTrainingPanel panel;
	private NavigationButton navButton;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Getter
	private NPC currentPet;

	@Getter
	private String currentPetName;

	@Getter
	private PetLevels currentPetLevels;

	private final Map<Skill, Integer> playerXp = new EnumMap<>(Skill.class);

	@Override
	protected void startUp() throws Exception
	{
		panel = injector.getInstance(PetTrainingPanel.class);

		//final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/skill_icons/overall.png");
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		navButton = NavigationButton.builder()
				.tooltip("Pet Training")
				.icon(icon)
				.priority(2)
				.panel(panel)
				.build();

		clientToolbar.addNavigation(navButton);

		// refresh the panel if the plugin was turned on while game running
		panel.refreshStatPanel(true);
		panel.setDropdown();
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			updateFollower();
			panel.refreshStatPanel(true);
			panel.setDropdown();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		saveCurrentPetStats();
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		saveCurrentPetStats();
	}

	@Subscribe
	public void onConfigSync(ConfigSync configSync)
	{
		saveCurrentPetStats();
	}

	@Provides
	PetTrainingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PetTrainingConfig.class);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event) {
		updateFollower();
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned npcDespawned) {
		if (npcDespawned.getActor() == currentPet) {
			log.debug("Follower despawned");
			// save and then delete the current values
			removeCurrentPet();
		}

		updateFollower();
	}

	public void removeCurrentPet() {
		// first update the UI
		panel.resetDisplayedPet(this.currentPetName, this.currentPetLevels);

		// save and remove from plugin
		saveCurrentPetStats();
		this.currentPetLevels = null;
		this.currentPet = null;
		this.currentPetName = null;
	}

	public void updateFollower() {
		NPC follower = client.getFollower();

		if (follower != null && follower != currentPet){
			if (currentPet != null) {
				// some weird situation where our follower got replaced immediately
				// save it and remove it
				removeCurrentPet();
			}
			// now we are confident we have no current pet and can add the new follower which isn't null
			this.currentPet = follower;
			String name = currentPet.getName();
			this.currentPetName = name;
			this.currentPetLevels = getExistingLevelsElseNew(name);

			log.debug("no current pet; create new or pull existing");

			panel.changeDisplayedPet(currentPetName, true);
			//panel.refreshStatPanel(true);
		}
	}

	public PetLevels getExistingLevelsElseNew(String name) {
		// this will get the existing pet levels if there are any saved, else return a new PetLevels
		PetLevels existingLevels = loadPetStats(name);

		if (existingLevels == null) {
			log.debug("nonexistent create new");
			return new PetLevels(name);
		}

		log.debug("found existing config; load it");
		return existingLevels;
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		final Skill skill = statChanged.getSkill();
		final int currentXp = statChanged.getXp();

		log.debug("xp drop {} {}", skill, currentXp);

        playerXp.putIfAbsent(skill, currentXp);

		if (this.currentPet != null) {
			final int currentPetLevel = currentPetLevels.getLevel(skill);
			int deltaXp = currentXp - playerXp.get(skill);
			currentPetLevels.addXp(skill, deltaXp);

			log.debug("{} GAINED {} {} XP FOR NEW TOTAL {}", currentPet.getName(), deltaXp, skill, currentPetLevels.getXp(skill));

			int newLevel = currentPetLevels.getLevel(skill);

			for (int i = currentPetLevel + 1; i <= newLevel; i++) {
				showLevelUpMessage(skill, i);
			}
		}

		playerXp.put(skill, currentXp);
		panel.refreshStatPanel(false);
	}

	public void showLevelUpMessage(Skill skill, Integer newLevel) {
		String levelUpStr = "~~%s just advanced a %s Level! Their %s Level is now %d.~~";
		String skillCapitalized = capitalize(skill.getName());
		String msg = String.format(levelUpStr, currentPet.getName(), skillCapitalized, skillCapitalized, newLevel);

		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
	}

	public String capitalize(String inputString) {
		if (inputString == null || inputString.isEmpty()) {
			return inputString;
		}

		// get the first character of the inputString
		char firstLetter = inputString.charAt(0);

		// convert it to an UpperCase letter
		char capitalFirstLetter = Character.toUpperCase(firstLetter);

		// return the output string by updating
		// the first char of the input string
		return capitalFirstLetter + inputString.substring(1);
	}

	public void saveCurrentPetStats() {
		if (currentPetLevels != null) {
			final String profile = configManager.getRSProfileKey();
			if (profile == null) {
				return;
			}

			if (Strings.isNullOrEmpty(profile)) {
				log.debug("Trying to save pet exp with no profile!");
				return;
			}

			String json = gson.toJson(currentPetLevels);
			configManager.setConfiguration(PetTrainingConfig.GROUP, profile, "levels_" + currentPetLevels.getName(), json);

		}
	}

	public PetLevels loadPetStats(String name) {
		String profile = configManager.getRSProfileKey();

		if (Strings.isNullOrEmpty(profile))
		{
			return null;
		}

		String json = configManager.getConfiguration(PetTrainingConfig.GROUP, profile, "levels_" + name);

		if (json == null)
		{
			return null;
		}

		return gson.fromJson(json, PetLevels.class);
	}

	public List<String> getAllSavedPets() {
		String profile = configManager.getRSProfileKey();

		if (Strings.isNullOrEmpty(profile))
		{
			return null;
		}

		List<String> idList = new ArrayList<>();
		List<String> configKeys = configManager.getRSProfileConfigurationKeys(PetTrainingConfig.GROUP, profile, "levels");

		for (String key : configKeys) {
			String prefix = "levels_";
			if (key.startsWith(prefix)) {
				idList.add(key.replace(prefix, ""));
			}
		}

		log.debug("all saved pet names {}", idList);

		return idList;
	}

	public void printLog(String str) {
		log.debug(str);
	}

}

